    // Ag yoksa, izin verilmemisse ya da web surumundeyse boyle olur.
    ;(adresCoz as jest.Mock).mockResolvedValue(null)

    render(<CheckInHaritasiEkrani />)

    await waitFor(() => expect(screen.getByText('Nilüfer')).toBeTruthy())
