  })
})

describe('mekanEkle', () => {
  it('ad, tur, konum ve cihaz konumunu rpc parametresi olarak gonderir', async () => {
    ;(supabase.rpc as jest.Mock).mockResolvedValue({
      data: {
        id: 'mekan-yeni',
