    )

    expect(supabase.rpc).toHaveBeenCalledWith('mekan_ekle', {
      p_ad: 'Yeni Kafe',
      p_tur: 'kafe',
      p_lat: 41.02,
      p_lng: 28.98,
      p_cihaz_lat: 41.0201,
      p_cihaz_lng: 28.9801,
      p_adres: null,
    })
    expect(sonuc.id).toBe('mekan-yeni')
  })

  it('cihaz mekana uzaksa sunucu hatasini firlatir', async () => {
